def last_visited_integers(words):
    numbers=[];answer=[];offset=0
    for word in words:
        if word==-1:
            offset+=1;answer.append(numbers[-offset] if offset<=len(numbers) else -1)
        else:
            numbers.append(word);offset=0
    return answer

